import React, { useState } from 'react';

const Experience = ({ data }) => {
  const [activeIdx, setActiveIdx] = useState(0);
  const experience = data || [];

  const accentColors = ['#e8799a', '#b882d4', '#e8b96a'];

  return (
    <section style={{ padding:'100px 0' }}>
      <div style={{ maxWidth:1100, margin:'0 auto', padding:'0 2rem' }}>

        <div style={{ textAlign:'center', marginBottom:60 }}>
          <span style={{ fontFamily:"'DM Mono'", fontSize:'0.78rem', letterSpacing:'0.3em', textTransform:'uppercase', color:'#e8799a', display:'block', marginBottom:'0.75rem' }}>
            ✦ 04. experience
          </span>
          <h2 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'clamp(2rem,5vw,3rem)', fontWeight:700, color:'#fdf0f4' }}>
            Work <span style={{ color:'#b882d4', fontStyle:'italic' }}>Experience</span>
          </h2>
          <div style={{ width:60, height:3, background:'linear-gradient(90deg,#e8799a,#b882d4)', margin:'1.5rem auto 0', borderRadius:2 }} />
        </div>

        <div style={{ display:'grid', gridTemplateColumns:'1fr 2fr', gap:'2rem', alignItems:'start' }} className="exp-grid">

          {/* Sidebar tabs */}
          <div style={{ display:'flex', flexDirection:'column', gap:'0.75rem' }}>
            {experience.map((exp, i) => (
              <button key={i} onClick={() => setActiveIdx(i)}
                style={{
                  padding:'1rem 1.25rem', borderRadius:14, textAlign:'left',
                  background: activeIdx === i ? `rgba(${accentColors[i%3] === '#e8799a' ? '232,121,154' : accentColors[i%3] === '#b882d4' ? '184,130,212' : '232,185,106'},0.12)` : 'rgba(34,18,40,0.72)',
                  border: `1px solid ${activeIdx === i ? accentColors[i%3] + '55' : 'rgba(232,121,154,0.1)'}`,
                  cursor:'pointer', transition:'all 0.3s ease',
                  borderLeft: `3px solid ${activeIdx === i ? accentColors[i%3] : 'transparent'}`,
                }}
              >
                <div style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1rem', fontWeight:700, color: activeIdx === i ? accentColors[i%3] : '#fdf0f4', marginBottom:'0.2rem' }}>{exp.company}</div>
                <div style={{ fontFamily:"'Nunito'", fontSize:'0.8rem', color:'rgba(253,240,244,0.5)' }}>{exp.duration}</div>
              </button>
            ))}
          </div>

          {/* Detail panel */}
          {experience[activeIdx] && (() => {
            const exp = experience[activeIdx];
            const color = accentColors[activeIdx % 3];
            return (
              <div style={{ background:'rgba(34,18,40,0.72)', border:`1px solid ${color}25`, borderRadius:22, backdropFilter:'blur(14px)', padding:'2rem' }}>
                {/* Header */}
                <div style={{ display:'flex', alignItems:'flex-start', gap:'1rem', marginBottom:'1.5rem' }}>
                  <div style={{ width:52, height:52, borderRadius:'50%', background:`${color}15`, border:`1.5px solid ${color}35`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:'1.5rem', flexShrink:0 }}>{exp.icon}</div>
                  <div>
                    <h3 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1.35rem', fontWeight:700, color:'#fdf0f4', marginBottom:'0.25rem' }}>{exp.role}</h3>
                    <div style={{ display:'flex', alignItems:'center', gap:'0.75rem', flexWrap:'wrap' }}>
                      <span style={{ fontFamily:"'Nunito'", fontSize:'0.88rem', color }}>{exp.company}</span>
                      <span style={{ width:4, height:4, borderRadius:'50%', background:'rgba(253,240,244,0.3)', display:'inline-block' }} />
                      <span style={{ fontFamily:"'DM Mono'", fontSize:'0.78rem', color:'rgba(253,240,244,0.45)' }}>{exp.duration}</span>
                    </div>
                  </div>
                </div>

                <p style={{ fontFamily:"'Nunito'", fontSize:'0.9rem', color:'rgba(253,240,244,0.65)', lineHeight:1.8, marginBottom:'1.5rem' }}>{exp.description}</p>

                {/* Achievements */}
                <div style={{ marginBottom:'1.5rem' }}>
                  <h4 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1rem', fontWeight:700, color:'#fdf0f4', marginBottom:'0.75rem' }}>Key Achievements</h4>
                  <ul style={{ listStyle:'none', display:'flex', flexDirection:'column', gap:'0.5rem' }}>
                    {exp.achievements?.map((a, ai) => (
                      <li key={ai} style={{ display:'flex', gap:'0.6rem', alignItems:'flex-start', fontFamily:"'Nunito'", fontSize:'0.87rem', color:'rgba(253,240,244,0.65)' }}>
                        <span style={{ color, flexShrink:0, marginTop:'0.1rem' }}>✿</span>
                        {a}
                      </li>
                    ))}
                  </ul>
                </div>

                {/* Technologies */}
                <div style={{ display:'flex', flexWrap:'wrap', gap:'0.4rem' }}>
                  {exp.technologies?.map((tech, ti) => (
                    <span key={ti} style={{ padding:'0.25rem 0.75rem', background:`${color}12`, border:`1px solid ${color}30`, borderRadius:'50px', fontFamily:"'DM Mono'", fontSize:'0.72rem', color }}>{tech}</span>
                  ))}
                </div>
              </div>
            );
          })()}
        </div>
      </div>

      <style>{`
        @media (max-width:768px) { .exp-grid { grid-template-columns:1fr !important; } }
      `}</style>
    </section>
  );
};

export default Experience;
